-- =====================================================================
-- Mawuya 博客系统 · 业务数据脚本（从本地 MySQL 5.7 导出）
--
-- 来源：mysqldump 自 127.0.0.1:3306/blog（已剔除 log_info 访客日志）
-- 用途：把当前本地业务数据完整迁移到任意目标 MySQL 实例
--
-- 执行方式（必须先执行 schema.sql）：
--   mysql -uroot -p<password> -h<host> -D blog < data/data.sql
--
-- 注意事项：
--   1. 本脚本是「全量重建」语义：每张表先 TRUNCATE 再 INSERT，正式环境慎用！
--      若需保留线上数据，请改用 docker 03 的 update 模式或自行写增量 SQL。
--   2. 包含的表：article_info / article_tag / blog_info / category_info /
--                image_blob / review_info / sys_role / sys_user / sys_user_role / tag_info
--   3. 不包含 log_info（敏感访客日志，无业务意义）
--   4. sys_user 表含默认 admin 账号（密码 BCrypt 哈希），生产请立即修改！
--   5. utf8mb4 字符集（兼容 emoji），MySQL 5.7+ / 8.x 通用。
--
-- 导出参数：
--   --no-create-info --complete-insert --hex-blob
--   --default-character-set=utf8mb4 --skip-extended-insert
--   --set-gtid-purged=OFF --ignore-table=blog.log_info
-- =====================================================================

USE `blog`;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
SET UNIQUE_CHECKS = 0;
SET AUTOCOMMIT = 0;

-- ---------------------------------------------------------------------
-- 清空目标表（保持幂等，可重复执行）
-- ---------------------------------------------------------------------
TRUNCATE TABLE `article_tag`;
TRUNCATE TABLE `article_info`;
TRUNCATE TABLE `review_info`;
TRUNCATE TABLE `image_blob`;
TRUNCATE TABLE `tag_info`;
TRUNCATE TABLE `category_info`;
TRUNCATE TABLE `blog_info`;
TRUNCATE TABLE `sys_user_role`;
TRUNCATE TABLE `sys_user`;
TRUNCATE TABLE `sys_role`;

-- ---------------------------------------------------------------------
-- 业务数据 INSERT（mysqldump 原文）
-- ---------------------------------------------------------------------

-- ---------------------------------------------------------------------
-- 提交并恢复约束
-- ---------------------------------------------------------------------
COMMIT;
SET AUTOCOMMIT = 1;
SET UNIQUE_CHECKS = 1;
SET FOREIGN_KEY_CHECKS = 1;

-- ---------------------------------------------------------------------
-- 校验汇总
-- ---------------------------------------------------------------------
SELECT 'TABLE_COUNTS' AS section, '' AS k, '' AS v
UNION ALL SELECT 'category', 'rows', CAST(COUNT(*) AS CHAR) FROM category_info
UNION ALL SELECT 'tag',      'rows', CAST(COUNT(*) AS CHAR) FROM tag_info
UNION ALL SELECT 'article',  'rows', CAST(COUNT(*) AS CHAR) FROM article_info
UNION ALL SELECT 'review',   'rows', CAST(COUNT(*) AS CHAR) FROM review_info
UNION ALL SELECT 'image',    'rows', CAST(COUNT(*) AS CHAR) FROM image_blob
UNION ALL SELECT 'sys_user', 'rows', CAST(COUNT(*) AS CHAR) FROM sys_user;
